// Checkout.jsx
import React, { useState } from 'react';
import './Checkout.css';

const metodosPago = [
  { id: 1, nombre: 'Tarjeta de Crédito/Débito', descripcion: 'Aceptamos Visa, MasterCard y American Express.' },
  { id: 2, nombre: 'PayPal', descripcion: 'Serás redirigido a PayPal para completar el pago.' },
  { id: 3, nombre: 'Nequi', descripcion: 'Te enviaremos un enlace de pago a tu número registrado en Nequi.' },
  { id: 4, nombre: 'Daviplata', descripcion: 'Recibirás instrucciones vía mensaje de texto.' },
  { id: 5, nombre: 'PSE', descripcion: 'Realiza el pago desde tu banco en línea con PSE.' },
];

function Checkout() {
  const [metodoSeleccionado, setMetodoSeleccionado] = useState(null);

  return (
    <div className="checkout-container">
      <div className="checkout-left">
        <div className="checkout-card">
          <h2>Método de Pago</h2>
          {metodosPago.map((metodo) => (
            <label
              key={metodo.id}
              className={`pago-opcion ${metodoSeleccionado === metodo.id ? 'seleccionado' : ''}`}
            >
              <input
                type="radio"
                name="metodoPago"
                value={metodo.id}
                checked={metodoSeleccionado === metodo.id}
                onChange={() => setMetodoSeleccionado(metodo.id)}
              />
              <div>
                <div className="nombre-metodo">{metodo.nombre}</div>
                <div className="descripcion-metodo">{metodo.descripcion}</div>
              </div>
            </label>
          ))}
        </div>
      </div>

      <div className="checkout-right">
        <h3>Resumen</h3>
        <div className="resumen-linea">
          <span>Subtotal:</span>
          <span>$137.000</span>
        </div>
        <div className="resumen-linea">
          <span>Envío:</span>
          <span>¡Gratis!</span>
        </div>
        <div className="resumen-total">
          <span>Total:</span>
          <span>$137.000</span>
        </div>
        <button className="btn-confirmar">Confirmar y Pagar</button>
        <p className="texto-condiciones">
          Al continuar, aceptas nuestros <a href="#">términos y condiciones</a>.
        </p>
      </div>
    </div>
  );
}

export default Checkout;
